/ {
    chosen {
        zephyr,input = &kbd_matrix_interrupt;
    };

    kbd_matrix_interrupt: kbd-matrix {
        compatible = "zephyr,kbd-matrix";
        row-gpios = <&gpio0 0 (GPIO_ACTIVE_LOW | GPIO_PULL_UP | GPIO_INT_EDGE_TO_ACTIVE)>,
                    <&gpio0 1 (GPIO_ACTIVE_LOW | GPIO_PULL_UP | GPIO_INT_EDGE_TO_ACTIVE)>,
                    <&gpio0 2 (GPIO_ACTIVE_LOW | GPIO_PULL_UP | GPIO_INT_EDGE_TO_ACTIVE)>,
                    <&gpio0 3 (GPIO_ACTIVE_LOW | GPIO_PULL_UP | GPIO_INT_EDGE_TO_ACTIVE)>;
        col-gpios = <&gpio0 4 GPIO_ACTIVE_HIGH>,
                    <&gpio0 5 GPIO_ACTIVE_HIGH>,
                    <&gpio0 6 GPIO_ACTIVE_HIGH>,
                    <&gpio0 7 GPIO_ACTIVE_HIGH>;
        debounce-interval-ms = <5>;
    };
};
